import { Link } from 'react-router-dom';

function Landing() {
  return (
    <div>
      <h1>Alumni Connect</h1>
      <p>Connecting students with alumni for guidance, events, and opportunities.</p>

      <Link to="/login">
        <button>Login</button>
      </Link>

      <Link to="/register">
        <button>Register</button>
      </Link>
    </div>
  );
}

export default Landing;
